export default "import {\n  SceneFlexLayout,\n  SceneTimeRange,\n  EmbeddedScene,\n  SceneFlexItem,\n  NestedScene,\n  SceneAppPage,\n  SceneAppPageState,\n  PanelBuilders,\n  SceneTimePicker,\n  SceneRefreshPicker,\n  SceneCSSGridLayout,\n  SceneControlsSpacer,\n  dataLayers,\n  SceneDataLayerControls,\n  SceneDataLayerSet,\n  SceneVariableSet,\n  TestVariable,\n  VariableValueSelectors,\n  behaviors,\n} from '@grafana/scenes';\nimport { getEmbeddedSceneDefaults, getQueryRunnerWithRandomWalkQuery } from './utils';\nimport { VariableRefresh } from '@grafana/schema';\n\nexport function getQueryControllerDemo(defaults: SceneAppPageState) {\n  const globalAnnotations = new dataLayers.AnnotationsDataLayer({\n    name: 'Global annotations',\n    query: {\n      datasource: {\n        type: 'testdata',\n        uid: 'gdev-testdata',\n      },\n      enable: true,\n      iconColor: 'yellow',\n      name: 'New annotation',\n      target: {\n        // @ts-ignore\n        lines: 10,\n        refId: 'Anno',\n        scenarioId: 'slow_query',\n        stringInput: '10s',\n      },\n    },\n  });\n\n  return new SceneAppPage({\n    ...defaults,\n    getScene: () => {\n      return new EmbeddedScene({\n        ...getEmbeddedSceneDefaults(),\n        $data: new SceneDataLayerSet({\n          layers: [globalAnnotations],\n        }),\n        $behaviors: [new behaviors.SceneQueryController()],\n        $variables: new SceneVariableSet({\n          variables: [\n            new TestVariable({\n              name: 'server',\n              query: 'A.*',\n              value: 'server',\n              delayMs: 1000,\n              options: [],\n              refresh: VariableRefresh.onTimeRangeChanged,\n            }),\n            new TestVariable({\n              name: 'pod',\n              query: 'A.$server.*',\n              value: 'pod',\n              delayMs: 3000,\n              options: [],\n              refresh: VariableRefresh.onDashboardLoad,\n            }),\n          ],\n        }),\n        controls: [\n          new VariableValueSelectors({}),\n          new SceneDataLayerControls(),\n          new SceneControlsSpacer(),\n          new SceneTimePicker({}),\n          new SceneRefreshPicker({ withText: true, primary: true }),\n        ],\n        body: new SceneFlexLayout({\n          direction: 'column',\n          children: [\n            new SceneFlexItem({\n              height: '320px',\n              body: new SceneCSSGridLayout({\n                autoRows: '320px',\n                children: [\n                  PanelBuilders.timeseries()\n                    .setTitle('2s query')\n                    .setData(getQueryRunnerWithRandomWalkQuery({ scenarioId: 'slow_query', stringInput: '2s' }))\n                    .build(),\n                  PanelBuilders.timeseries()\n                    .setTitle('3s query')\n                    .setData(getQueryRunnerWithRandomWalkQuery({ scenarioId: 'slow_query', stringInput: '3s' }))\n                    .build(),\n                  PanelBuilders.timeseries()\n                    .setTitle('5s query')\n                    .setData(getQueryRunnerWithRandomWalkQuery({ scenarioId: 'slow_query', stringInput: '5s' }))\n                    .build(),\n                ],\n              }),\n            }),\n            new SceneFlexItem({\n              body: getInnerScene('Inner scene1'),\n            }),\n          ],\n        }),\n      });\n    },\n  });\n}\n\nexport function getInnerScene(title: string) {\n  const nestedAnnotationsDataLayer = new dataLayers.AnnotationsDataLayer({\n    name: 'Nested annotations',\n    query: {\n      datasource: {\n        type: 'testdata',\n        uid: 'gdev-testdata',\n      },\n      enable: true,\n      iconColor: 'red',\n      name: 'New annotation',\n      target: {\n        // @ts-ignore\n        lines: 10,\n        refId: 'Anno',\n        scenarioId: 'slow_query',\n        stringInput: '10s',\n      },\n    },\n  });\n\n  const scene = new NestedScene({\n    title: title,\n    canCollapse: true,\n    body: new SceneCSSGridLayout({\n      children: [\n        PanelBuilders.timeseries()\n          .setTitle('2s query')\n          .setData(getQueryRunnerWithRandomWalkQuery({ scenarioId: 'slow_query', stringInput: '2s' }))\n          .build(),\n        PanelBuilders.timeseries()\n          .setTitle('3s query')\n          .setData(getQueryRunnerWithRandomWalkQuery({ scenarioId: 'slow_query', stringInput: '3s' }))\n          .build(),\n        PanelBuilders.timeseries()\n          .setTitle('5s query')\n          .setData(getQueryRunnerWithRandomWalkQuery({ scenarioId: 'slow_query', stringInput: '5s' }))\n          .build(),\n      ],\n    }),\n    $timeRange: new SceneTimeRange(),\n    $data: new SceneDataLayerSet({\n      layers: [nestedAnnotationsDataLayer],\n    }),\n    $behaviors: [new behaviors.SceneQueryController()],\n    controls: [\n      new SceneDataLayerControls(),\n      new SceneControlsSpacer(),\n      new SceneTimePicker({}),\n      new SceneRefreshPicker({ withText: true }),\n    ],\n  });\n\n  return scene;\n}\n";